# The figurine has been released near the stand and both grippers are open.
# Use the reserved actions to return both arms to the saved starting joints and check completion.
s = get_observation()['state']
starts = {k:list(s[k]) for k in ['left_arm_joint_state','right_arm_joint_state']}
action = {k:list(v) for k,v in home.items()}
for i in range(38):
    alpha = min(1.0, float(i+1)/30)
    for k in starts:
        action[k] = [(1-alpha)*float(starts[k][j])+alpha*float(home[k][j]) for j in range(6)]
    action['left_ee_joint_state'] = [1]
    action['right_ee_joint_state'] = [1]
    obs, reward, terminated, truncated, info = step(action)
    if terminated or truncated:
        print('final', reward, terminated, truncated, info)
        break

